// 将门类名 + 学位类型 + 可选专业映射为 ADMISSION_SCORES 中的 key
export function mapCategoryToScoreKey(category, degree, major) {
  const short = degree === 'xueshuo' ? '学硕' : '专硕';
  const exactKey = `${category}-${short}`;

  // Build candidate keys in priority order
  const keys = [];
  if (major && major !== '不限专业') {
    const majorName = major.replace(/\([^)]*\)/g, '').trim();
    keys.push(`${category}-${majorName}-${short}`);
  }
  keys.push(exactKey); // "工学-学硕" as fallback

  // Collect keys from ALL universities for fuzzy matching
  const allKeys = new Set();
  for (const uni of Object.values(ADMISSION_SCORES)) {
    for (const k of Object.keys(uni)) {
      allKeys.add(k);
    }
  }

  // Step 1: exact match in known keys
  for (const k of keys) {
    if (allKeys.has(k)) return k;
  }

  // Step 2: fuzzy match for the specific major (exact match within key)
  if (major && major !== '不限专业') {
    const majorName = major.replace(/\([^)]*\)/g, '').trim();
    for (const k of allKeys) {
      if (k.endsWith(`-${short}`) && k.includes(majorName)) return k;
    }
  }

  // Step 3: 大类本身做模糊匹配（如 电子信息/机械/... → 电子信息/机械-专硕）
  // 选了细分专业时不做大类模糊——避免土木水利匹配到建筑/土木
  if (degree === 'zhuanshuo' && (!major || major === '不限专业')) {
    const catParts = category.split('/');
    for (const k of allKeys) {
      if (!k.endsWith(`-${short}`)) continue;
      const keyCat = k.replace(`-${short}`, '');
      const keyParts = keyCat.split('/');
      if (keyParts.every(kp => catParts.some(cp => cp.includes(kp) || kp.includes(cp)))) {
        return k;
      }
    }
  }

  // Step 4: fallback to exactKey
  return exactKey;
}

/** 获取某院校某门类的历年录取分数。仅返回真实数据，无数据返回null */
export function getAdmissionScores(universityName, category, degree, major) {
  const uni = ADMISSION_SCORES[universityName];
  if (!uni) return null;

  const key = mapCategoryToScoreKey(category, degree, major);
  const scores = uni[key];
  if (!scores) return null;

  const years = ['2026', '2025', '2024', '2023', '2022'];
  const result = years
    .map((y) => ({ year: y, score: scores[y] || null }))
    .filter((item) => item.score !== null && item.score > 0);

  return result.length > 0 ? result : null;
}

// 根据院校层次和学科门类自动生成预估录取分数线
// 算法：基于该门类历年国家线 + 院校层次附加分（985顶尖+55~70, 985重点+35~50, 211+8~30, 双一流+3~12, 双非-5~+8）
export function generateEstimatedScores(universityName, category, degree) {
  const uni = findUniversity(universityName);
  if (!uni) return null;

  // 检查大学类型是否与该专业门类兼容
  if (!isCategoryCompatible(universityName, category)) return null;

  // 综合/师范/民族类双非零数据 → 不预估（无法确认专业方向）
  // 理工/农业/医药等专业型院校 → 即使零数据也生成预估（类型已表明专业方向）
  const hasRealData = !!ADMISSION_SCORES[universityName];
  if (!hasRealData && uni.level === '双非') {
    const uncertainTypes = ['综合', '师范', '民族'];
    if (uncertainTypes.includes(uni.type || '综合')) return null;
  }

  // 获取该门类A区国家线(作为基准)
  const nl = getAllYearLines(degree, category, 'A');
  if (nl.length === 0) return null;

  // 确定层次附加分
  const margin = getTierMargin(universityName, uni.level);

  // B区院校在国家线上减一些
  const zoneAdjust = uni.zone === 'B' ? -8 : 0;

  // 生成各年预估分
  return nl.map((n) => ({
    year: n.year,
    score: Math.max(0, n.score + margin + zoneAdjust),
  }));
}

/**
 * 院校类型 → 默认兼容学科门类矩阵
 *
 * 规则：只在院校"确定有"该门类硕博点时才纳入兼容范围。
 * 综合/师范/民族 默认不含工/农/医/军事/交叉学科（除非有真实数据证明开设了）
 */
const _ALL_CATEGORIES = ['哲学','经济学','法学','教育学','文学','历史学','理学','工学','农学','医学','军事学','管理学','艺术学','交叉学科'];
const COMMON_CATEGORIES = ['哲学','经济学','法学','教育学','文学','历史学','理学','管理学','艺术学'];

const TYPE_COMPATIBILITY = {
  // 综合/师范/民族：默认只含基础文理学科，工/农/医/军事/交叉需有真实数据
  '综合': COMMON_CATEGORIES,
  '师范': COMMON_CATEGORIES,
  '民族': COMMON_CATEGORIES,
  // 理工类：主打工科+理学
  '理工': ['工学', '理学', '管理学', '经济学', '交叉学科'],
  '电子': ['工学', '理学', '管理学'],
  '邮电': ['工学', '理学', '管理学'],
  '交通': ['工学', '理学', '管理学'],
  '航空': ['工学', '理学', '管理学'],
  '建筑': ['工学', '管理学'],
  '化工': ['工学', '理学', '管理学'],
  '地质': ['理学', '工学'],
  '矿业': ['工学', '理学'],
  '石油': ['工学', '理学'],
  '水利': ['工学', '理学'],
  '电力': ['工学', '管理学'],
  '纺织': ['工学', '管理学'],
  '轻工': ['工学', '理学'],
  '海洋': ['理学', '工学', '农学'],
  // 农林类
  '农业': ['农学', '理学', '工学', '管理学'],
  '林业': ['农学', '理学', '工学'],
  // 医药类
  '医药': ['医学', '理学'],
  // 文史法经类
  '财经': ['经济学', '管理学', '法学', '文学'],
  '政法': ['法学', '管理学', '文学'],
  '语言': ['文学', '教育学', '法学'],
  '艺术': ['艺术学', '文学'],
  '体育': ['教育学'],
};

/** 判断院校对该门类是否有真实数据（人工录入的非预估值） */
function hasRealCategoryData(universityName, category) {
  const uniData = ADMISSION_SCORES[universityName];
  if (!uniData) return false;
  const short = category.includes('学硕') || category.includes('专硕') ? '' : '-学硕';
  const prefix = category + short;
  // 检查是否存在以该门类开头的真实数据key
  return Object.keys(uniData).some(k => k.startsWith(prefix) || k.startsWith(category));
}

function isCategoryCompatible(universityName, category) {
  const uni = findUniversity(universityName);
  if (!uni) return false; // 未知院校不兼容
  const type = uni.type || '综合';
  const baseAllowed = TYPE_COMPATIBILITY[type];

  // 1. 类型默认兼容 → 放行
  if (Array.isArray(baseAllowed) && baseAllowed.includes(category)) return true;

  // 2. 不在默认兼容列表，但该院校有真实数据 → 放行（证明其确实开设了此专业）
  if (hasRealCategoryData(universityName, category)) return true;

  // 3. 否则不兼容
  return false;
}

/**
 * 根据院校层次返回相对国家线的附加分
 */
export function getTierMargin(universityName, level) {
  // C9 / 顶尖985
  const C9 = [
    '清华大学',
    '北京大学',
    '复旦大学',
    '上海交通大学',
    '浙江大学',
    '中国科学技术大学',
    '南京大学',
    '哈尔滨工业大学',
    '西安交通大学',
  ];
  // 强势985
  const TOP985 = [
    '华中科技大学',
    '武汉大学',
    '中山大学',
    '同济大学',
    '北京航空航天大学',
    '北京理工大学',
    '东南大学',
    '天津大学',
    '南开大学',
    '中国人民大学',
    '国防科技大学',
    '电子科技大学',
    '华南理工大学',
    '四川大学',
  ];
  // 强势211
  const TOP211 = [
    '北京邮电大学',
    '北京交通大学',
    '北京科技大学',
    '北京工业大学',
    '南京航空航天大学',
    '南京理工大学',
    '苏州大学',
    '上海大学',
    '西安电子科技大学',
    '西南交通大学',
    '武汉理工大学',
    '华东理工大学',
    '中国政法大学',
    '中央财经大学',
    '上海财经大学',
    '对外经济贸易大学',
    '中南财经政法大学',
    '西南财经大学',
    '暨南大学',
    '中国传媒大学',
    '中国石油大学(华东)',
    '河海大学',
    '江南大学',
    '西南大学',
    '华中师范大学',
    '东北师范大学',
    '南京师范大学',
  ];

  if (C9.includes(universityName)) return 60 + Math.floor(Math.random() * 10); // 60-69
  if (TOP985.includes(universityName)) return 38 + Math.floor(Math.random() * 15); // 38-52
  if (level === '985') return 28 + Math.floor(Math.random() * 14); // 28-41
  if (TOP211.includes(universityName)) return 18 + Math.floor(Math.random() * 14); // 18-31
  if (level === '211') return 10 + Math.floor(Math.random() * 14); // 10-23
  if (level === '双一流') return 3 + Math.floor(Math.random() * 11); // 3-13
  if (
    universityName === '深圳大学' ||
    universityName === '杭州电子科技大学' ||
    universityName === '重庆邮电大学' ||
    universityName === '广东工业大学' ||
    universityName === '浙江工业大学' ||
    universityName === '燕山大学' ||
    universityName === '西南政法大学' ||
    universityName === '华东政法大学' ||
    universityName === '东北财经大学'
  ) {
    return 5 + Math.floor(Math.random() * 10); // 强势双非 5-14
  }
  return -3 + Math.floor(Math.random() * 10); // 普通双非 -3~+6
}

/** 更新或添加某院校某门类的录取分 */
export function updateAdmissionScore(universityName, category, degree, major, year, score) {
  if (!ADMISSION_SCORES[universityName]) {
    ADMISSION_SCORES[universityName] = {};
  }
  const key = mapCategoryToScoreKey(category, degree, major);
  if (!ADMISSION_SCORES[universityName][key]) {
    ADMISSION_SCORES[universityName][key] = {};
  }
  ADMISSION_SCORES[universityName][key][year] = score;
}
